<?php require_once 'includes/functions.php';$u=login_required('patient');$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare('SELECT r.*,d.name donor_name FROM blood_requests r JOIN users d ON d.user_id=r.donor_id WHERE r.request_id=? AND r.patient_id=?');$s->execute([$id,$u['user_id']]);$r=$s->fetch();if(!$r)exit('Request not found');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare("SELECT * FROM verification_codes WHERE request_id=? AND status='Active' AND expires_at>NOW()");$s->execute([$id]);$v=$s->fetch();if($r['status']!=='Donation_Marked'||!$v||!password_verify(trim($_POST['code']??''),$v['code_hash']))$err='Invalid, expired, or unexpected verification code.';else{$p=db();$p->beginTransaction();try{$p->prepare("UPDATE blood_requests SET status='Confirmed' WHERE request_id=?")->execute([$id]);$p->prepare("UPDATE donations SET status='Confirmed' WHERE request_id=?")->execute([$id]);$p->prepare("UPDATE verification_codes SET status='Used' WHERE request_id=?")->execute([$id]);$p->prepare("UPDATE donor_profiles SET last_donation=CURDATE(),availability='Unavailable' WHERE user_id=?")->execute([$r['donor_id']]);$p->commit();notice((int)$r['donor_id'],'Patient confirmed donation for request #'.$id,'donation');flash('Donation confirmed. You may leave a review.');go('review.php?id='.$id);}catch(Throwable $e){$p->rollBack();$err='Confirmation failed.';}}}$title='Confirm donation';require 'includes/header.php';?><section class="form"><h1>Confirm donation</h1><p>Donor: <?=e($r['donor_name'])?></p><?php if($err):?><p class="alert error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><label>6-digit code<input name="code" pattern="[0-9]{6}" required></label><button class="btn">Verify and confirm</button></form></section><?php require 'includes/footer.php';?>